Consider the following simple implementation of a hybrid user-level/kernel-level lock.
    class TooSimpleFutexLock { 
      private: 
        int val; 

      public: 
        TooSimpleMutex() : val (0) { }  // Constructor 

        void acquire () { 
            int c; 
            // atomic_inc returns *old* value 
            while ((c = atomic_inc (val)) != 0) { 
                futex_wait (&val, c + 1); 
            } 
        } 

        void release () { 
            val = 0; 
            futex_wake (&val, 1); 
        } 
    };
